/**
 * Creational Design Patterns in TypeScript
 * Patterns for creating objects flexibly and efficiently.
 */

// ---- 1. Singleton ----
class DatabaseConnection {
  private static instance: DatabaseConnection;
  private constructor() { /* connect to DB */ }

  static getInstance(): DatabaseConnection {
    if (!DatabaseConnection.instance) {
      DatabaseConnection.instance = new DatabaseConnection();
    }
    return DatabaseConnection.instance;
  }

  query(sql: string) { return `Result of: ${sql}`; }
}

// Usage: always same instance
const db1 = DatabaseConnection.getInstance();
const db2 = DatabaseConnection.getInstance();
console.log(db1 === db2); // true

// ---- 2. Factory Method ----
interface Logger {
  log(msg: string): void;
}

class ConsoleLogger implements Logger {
  log(msg: string) { console.log(`[CONSOLE] ${msg}`); }
}

class FileLogger implements Logger {
  log(msg: string) { /* write to file */ }
}

class CloudLogger implements Logger {
  log(msg: string) { /* send to cloud */ }
}

function createLogger(type: 'console' | 'file' | 'cloud'): Logger {
  const loggers = { console: ConsoleLogger, file: FileLogger, cloud: CloudLogger };
  return new loggers[type]();
}

// ---- 3. Builder Pattern ----
class QueryBuilder {
  private table = '';
  private conditions: string[] = [];
  private selectedColumns: string[] = ['*'];
  private limitValue?: number;
  private orderByColumn?: string;

  from(table: string) { this.table = table; return this; }
  select(...cols: string[]) { this.selectedColumns = cols; return this; }
  where(condition: string) { this.conditions.push(condition); return this; }
  limit(n: number) { this.limitValue = n; return this; }
  orderBy(col: string) { this.orderByColumn = col; return this; }

  build(): string {
    let query = `SELECT ${this.selectedColumns.join(', ')} FROM ${this.table}`;
    if (this.conditions.length) query += ` WHERE ${this.conditions.join(' AND ')}`;
    if (this.orderByColumn) query += ` ORDER BY ${this.orderByColumn}`;
    if (this.limitValue) query += ` LIMIT ${this.limitValue}`;
    return query;
  }
}

// Usage — fluent interface
const query = new QueryBuilder()
  .from('users')
  .select('id', 'name', 'email')
  .where('active = true')
  .where('age >= 18')
  .orderBy('name')
  .limit(50)
  .build();
// SELECT id, name, email FROM users WHERE active = true AND age >= 18 ORDER BY name LIMIT 50

// ---- 4. Prototype ----
interface Cloneable<T> { clone(): T; }

class Config implements Cloneable<Config> {
  constructor(
    public host: string,
    public port: number,
    public options: Record<string, any> = {}
  ) {}

  clone(): Config {
    return new Config(this.host, this.port, { ...this.options });
  }
}

const baseConfig = new Config('localhost', 5432, { ssl: true });
const testConfig = baseConfig.clone();
testConfig.host = 'test-db'; // doesn't affect baseConfig

// ---- 5. Abstract Factory ----
interface Button { render(): string; onClick(): void; }
interface Dialog { show(): void; }

interface UIFactory {
  createButton(): Button;
  createDialog(): Dialog;
}

class MaterialUI implements UIFactory {
  createButton(): Button { return { render: () => '<MaterialButton/>', onClick: () => {} }; }
  createDialog(): Dialog { return { show: () => console.log('Material Dialog') }; }
}

// Switch entire UI theme by swapping factory
function buildUI(factory: UIFactory) {
  const btn = factory.createButton();
  const dlg = factory.createDialog();
  return { btn, dlg };
}

import React, { memo, useMemo, useCallback, useTransition, useDeferredValue, useRef } from 'react';

/**
 * React Performance Optimization Patterns
 */

// 1. React.memo — prevent re-render if props unchanged
const ExpensiveList = memo(function ExpensiveList({ items }: { items: number[] }) {
  return (
    <ul>
      {items.map(item => <li key={item}>{item}</li>)}
    </ul>
  );
}, (prevProps, nextProps) => {
  // Custom comparison — return true to SKIP re-render
  return prevProps.items.length === nextProps.items.length;
});

// 2. useMemo — memoize expensive computation
function FilteredList({ items, filter }: { items: string[]; filter: string }) {
  const filtered = useMemo(
    () => items.filter(item => item.toLowerCase().includes(filter.toLowerCase())),
    [items, filter]  // only recompute when these change
  );
  return <ul>{filtered.map(i => <li key={i}>{i}</li>)}</ul>;
}

// 3. useCallback — stable function reference for child props
function Parent() {
  const [count, setCount] = React.useState(0);

  // Without useCallback: new function every render → Child re-renders
  // With useCallback: same reference → Child skips re-render
  const handleClick = useCallback(() => {
    console.log('clicked');
  }, []);  // no deps = created once

  return (
    <div>
      <p>{count}</p>
      <button onClick={() => setCount(c => c+1)}>Inc</button>
      <ExpensiveChild onAction={handleClick} />
    </div>
  );
}

const ExpensiveChild = memo(({ onAction }: { onAction: () => void }) => {
  console.log('ExpensiveChild rendered');
  return <button onClick={onAction}>Action</button>;
});

// 4. useTransition — mark state update as non-urgent
function SearchPage() {
  const [query, setQuery] = React.useState('');
  const [results, setResults] = React.useState<string[]>([]);
  const [isPending, startTransition] = useTransition();

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value);  // urgent: update input immediately
    startTransition(() => {
      // non-urgent: can be interrupted by more urgent updates
      setResults(expensiveSearch(e.target.value));
    });
  };

  return (
    <div>
      <input value={query} onChange={handleSearch} />
      {isPending ? <p>Loading...</p> : <ul>{results.map(r => <li key={r}>{r}</li>)}</ul>}
    </div>
  );
}

function expensiveSearch(q: string): string[] { return []; }

// 5. useDeferredValue — defer re-rendering of non-critical UI
function DeferredSearch({ query }: { query: string }) {
  const deferredQuery = useDeferredValue(query);
  const isStale = query !== deferredQuery;

  const results = useMemo(() => expensiveSearch(deferredQuery), [deferredQuery]);

  return (
    <div style={{ opacity: isStale ? 0.5 : 1 }}>
      {results.map(r => <div key={r}>{r}</div>)}
    </div>
  );
}

// 6. Virtual scrolling (render only visible items)
function VirtualList({ items, itemHeight = 50, windowHeight = 500 }: {
  items: any[];
  itemHeight?: number;
  windowHeight?: number;
}) {
  const [scrollTop, setScrollTop] = React.useState(0);
  const startIndex = Math.floor(scrollTop / itemHeight);
  const visibleCount = Math.ceil(windowHeight / itemHeight) + 1;
  const visibleItems = items.slice(startIndex, startIndex + visibleCount);

  return (
    <div
      style={{ height: windowHeight, overflowY: 'auto' }}
      onScroll={e => setScrollTop((e.target as HTMLDivElement).scrollTop)}
    >
      <div style={{ height: items.length * itemHeight, position: 'relative' }}>
        {visibleItems.map((item, i) => (
          <div
            key={startIndex + i}
            style={{ position: 'absolute', top: (startIndex + i) * itemHeight, height: itemHeight }}
          >
            {item}
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Node.js Streams — Process large data efficiently.
 * Streams: pipe data in chunks → low memory, high throughput.
 */

const { Readable, Writable, Transform, pipeline } = require('stream');
const { promisify } = require('util');
const pipelineAsync = promisify(pipeline);
const fs = require('fs');
const zlib = require('zlib');

// 1. Readable stream — generate data on demand
class NumberStream extends Readable {
  constructor(limit) {
    super({ objectMode: true });
    this.current = 1;
    this.limit = limit;
  }

  _read() {
    if (this.current <= this.limit) {
      this.push(this.current++);
    } else {
      this.push(null);  // signal end of stream
    }
  }
}

// 2. Transform stream — transform data as it flows
class CSVParser extends Transform {
  constructor() {
    super({ readableObjectMode: true });
    this.headers = null;
  }

  _transform(chunk, encoding, callback) {
    const lines = chunk.toString().split('\n');
    for (const line of lines) {
      if (!line.trim()) continue;
      const values = line.split(',');
      if (!this.headers) {
        this.headers = values;
      } else {
        const obj = Object.fromEntries(this.headers.map((h, i) => [h, values[i]]));
        this.push(obj);
      }
    }
    callback();
  }
}

// 3. Process large CSV file with low memory
async function processLargeCSV(inputPath) {
  const results = [];

  await pipelineAsync(
    fs.createReadStream(inputPath),
    new CSVParser(),
    new Writable({
      objectMode: true,
      write(obj, _, callback) {
        // Process each row without loading entire file
        results.push(obj);
        callback();
      }
    })
  );

  return results;
}

// 4. Gzip a file stream
async function gzipFile(input, output) {
  await pipelineAsync(
    fs.createReadStream(input),
    zlib.createGzip(),
    fs.createWriteStream(output)
  );
  console.log(`Compressed ${input} → ${output}`);
}

// 5. HTTP streaming response
const http = require('http');
const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  const numbers = new NumberStream(1000000);
  res.write('[');
  let first = true;
  numbers.on('data', (num) => {
    res.write((first ? '' : ',') + num);
    first = false;
  });
  numbers.on('end', () => { res.write(']'); res.end(); });
});

// 6. Async iteration (modern approach)
async function* generatePages(totalPages) {
  for (let page = 1; page <= totalPages; page++) {
    // Simulate API fetch
    yield await fetchPage(page);
  }
}

async function processAllPages() {
  for await (const page of generatePages(100)) {
    // Process each page as it arrives, never holds all in memory
    console.log(`Processed page with ${page.length} items`);
  }
}

async function fetchPage(n) { return []; }  // placeholder

